$ErrorActionPreference='Stop';$r='C:\OttrinTreeUIQA\results';if($env:USERNAME-ne'OttrinTreeUIQA'){throw 'Wrong user'}
$env:OTTRIN_WINDOWS_CROSS_VOLUME_ROOT='R:\TreeQAPlatform';if(Test-Path $env:OTTRIN_WINDOWS_CROSS_VOLUME_ROOT){throw 'Fixture exists'};New-Item -ItemType Directory $env:OTTRIN_WINDOWS_CROSS_VOLUME_ROOT|Out-Null
try {$p=Start-Process C:\OttrinTreeUIQA\platform.exe -ArgumentList 'move_transaction::windows_source_tests::windows_native_cross_volume_replace_batch_moves_unoccupied_files_and_trees --exact --ignored --nocapture --test-threads=1' -PassThru -RedirectStandardOutput "$r\platform.stdout" -RedirectStandardError "$r\platform.stderr";$null=$p.Handle;try {if(-not$p.WaitForExit(120000)){throw 'Native regression still live'};@{exit=$p.ExitCode}|ConvertTo-Json|Set-Content "$r\PLATFORM.json";if($p.ExitCode-ne0){exit 1}}finally {if(-not$p.HasExited){& "$env:WINDIR\System32\taskkill.exe" /PID $p.Id /T /F|Out-Null}}} finally {Remove-Item $env:OTTRIN_WINDOWS_CROSS_VOLUME_ROOT -Recurse -Force}
